solutionCode:
open class Subsystem(val name: String)

class DriveSubsystem : Subsystem("Drivetrain") {
    fun drive() {
        println("Driving forward!")
    }
}

class ShooterSubsystem : Subsystem("Shooter") {
    fun shoot() {
        println("Launching game piece!")
    }
}

fun activateSubsystem(sub: Subsystem) {
    if (sub is DriveSubsystem) {
        sub.drive()
    } else if (sub is ShooterSubsystem) {
        sub.shoot()
    } else {
        println("No special action for ${sub.name}")
    }
}

