import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testDriveSubsystem() {
        val output = captureOutput { activateSubsystem(DriveSubsystem()) }
        Assert.assertEquals("Driving forward!", output.trim())
    }

    @Test
    fun testShooterSubsystem() {
        val output = captureOutput { activateSubsystem(ShooterSubsystem()) }
        Assert.assertEquals("Launching game piece!", output.trim())
    }

    @Test
    fun testGenericSubsystem() {
        val output = captureOutput { activateSubsystem(Subsystem("Intake")) }
        Assert.assertEquals("No special action for Intake", output.trim())
    }

    @Test
    fun testAnotherGenericSubsystem() {
        val output = captureOutput { activateSubsystem(Subsystem("Climber")) }
        Assert.assertEquals("No special action for Climber", output.trim())
    }
}

fun captureOutput(block: () -> Unit): String {
    val stream = java.io.ByteArrayOutputStream()
    val ps = java.io.PrintStream(stream)
    val old = System.out
    System.setOut(ps)
    block()
    System.setOut(old)
    return stream.toString()
}
